cat <<'EOF' > /tmp/brute.go
package main
import ( "fmt"; "go/scanner"; "go/token")
func main(){
 src:=`package main
func f1() {
a := 1
b := 2
}
func f2() {
x := 99
a := 1
b := 2
}
`
