   seen := map[string][]int{}
   for i:=0; i+length <= len(toks); i++ {
     key := fmt.Sprint(toks[i:i+length])
     seen[key] = append(seen[key], i)
   }
   for k,v := range seen {
     if len(v)>=2 {
       fmt.Printf("len %d repeat %v at %v\n", length, k, v)
     }
   }
 }
}
EOF
go run /tmp/brute.go

# Should show repeats.

