# For many cases, excluding "}" matches max: e.g., func {} (6->5), func { { } } (8->6) excluding "}" gives 6, func if true {} (10->8) excluding "}" gives 8, func if true { a:=1 } (13->11) excluding "}" gives 11, func a:=1 (9->8) excluding "}" gives 8, func a:=1 b:=2 (12->11) excluding "}" gives 11.
# For switch case with case: excluding "}" gave 14 but need 13, so not match. Excluding ")" and "}" gave 13 which matches.
# For that switch case, excluding "}" alone gave 14, need 13, so need to exclude one more token: ")"? Let's compute tokens for switch: [func IDENT ( ) { switch IDENT { case IDENT : IDENT := INT } }]. Count: tokens list length 16. Excluding "}" (2 of them) gives 14. Need 13, so need to exclude one more token: ")"? That would give 13 (since there is one ")" token). Indeed exclude {")", "}"} gives 13 and matches.

# Let's test more switch cases: earlier switch true { } per10 max8 diff2. Tokens: func IDENT ( ) { switch IDENT { } } . That's tokens: func, IDENT, (, ), {, switch, IDENT, {, }, } =10. Excluding "}" (2) gives 8 => matches. Excluding ")" and "}" would give 7, not match. So for empty switch, excluding "}" matches, not ")"+"}".

# So for switch with case, why need exclude ")" as well? Let's examine token list: for switch true { case true: a:=1 } tokens = func IDENT ( ) { switch IDENT { case IDENT : IDENT := INT } }. That's: func(1), IDENT(2), ((3), )(4), {(5), switch(6), IDENT(7), {(8), case(9), IDENT(10), :(11), IDENT(12), :=(13), INT(14), }(15), }(16). So there are 2 "}"? Actually we have two closing braces: one for switch, one for func. That's positions 15 and 16. So "{" appears twice (func and switch). "(" ")" each once.

# Excluding "}" removes 2 tokens, leaving 14. Need 13, so one more token excluded. Which token? Could be ":"? Let's test various combos.

cat <<'EOF' > /tmp/find_exclude2.go
package main
import (
 "fmt"
 "os"
 "os/exec"
 "go/scanner"
 "go/token"
)
func tokens(src string) []string {
 fset:=token.NewFileSet()
 file:=fset.AddFile("a.go", fset.Base(), len(src))
 var s scanner.Scanner
 s.Init(file, []byte(src), nil, 0)
 res:=[]string{}
 for {
  _, tok, _ := s.Scan()
  if tok==token.EOF {break}
  if tok==token.SEMICOLON {continue}
  res=append(res, tok.String())
 }
 return res
}
func test(src string){
 toks:=tokens(src)
 fileSrc:=fmt.Sprintf("package main\n%s\n%s\n", src, src)
 os.WriteFile("/tmp/collect_tmp.go", []byte(fileSrc), 0644)
 max:=0
 for t:=1; t<=100; t++ {
  cmd:=exec.Command("/workspace/executable", "-t", fmt.Sprintf("%d", t), "/tmp/collect_tmp.go")
  out,_:=cmd.CombinedOutput()
  s:=string(out)
  found:=false
  for i:=0;i<=len(s)-5;i++{if s[i:i+5]=="found"{found=true;break}}
  if found{max=t}else{if t>max+1{break}}
 }
 fmt.Printf("src=%q\n toks=%v total=%d max=%d diff=%d\n", src, toks, len(toks), max, len(toks)-max)
 // try to find single token type whose count equals diff
 counts:=map[string]int{}
 for _, tk:=range toks{counts[tk]++}
 fmt.Printf(" counts %v\n", counts)
 // try combinations of up to 2 token types
 for tk, cnt:=range counts{
  if cnt==len(toks)-max{
   fmt.Printf("  single token %q count %d matches diff\n", tk, cnt)
  }
 }
 // try pairs
 for tk1,c1:=range counts{
  for tk2,c2:=range counts{
   if tk1>=tk2{continue}
   if c1+c2==len(toks)-max{
    fmt.Printf("  pair %q+%q counts %d+%d=%d matches diff\n", tk1,tk2,c1,c2,c1+c2)
   }
  }
 }
 fmt.Println()
}
func main(){
 test("func f1() { switch true { case true: a:=1 } }")
 test("func f1() { switch true { case true: } }")
 test("func f1() { switch true { } }")
 test("func f1() { select { case true: a:=1 } }")
 test("func f1() { if true { a:=1 } }")
}
EOF
go run /tmp/find_exclude2.go

