package main
import (
 "fmt"
 "go/scanner"
 "go/token"
 "os"
 "sort"
 "strings"
)
type GlobalToken struct {
 id int
 raw string // raw token string for brace counting
 file string
 line int
}
func test(fileList []string, thresh int){
 type FileTokens struct {
  path string
  tokens []struct{id int; raw string; line int}
 }
 var filesTokens []FileTokens
 for _, fpath := range fileList {
  data, _ := os.ReadFile(fpath)
  fset := token.NewFileSet()
  file := fset.AddFile(fpath, -1, len(data))
  var s scanner.Scanner
  s.Init(file, data, nil, 0)
  var toks []struct{id int; raw string; line int}
  for {
   pos, tok, lit := s.Scan()
   if tok==token.EOF {break}
   if tok==token.COMMENT||tok==token.SEMICOLON{continue}
   var nid int
   raw := tok.String()
   if tok==token.IDENT {nid=1; raw="IDENT"}
   else if tok==token.INT||tok==token.FLOAT||tok==token.IMAG||tok==token.CHAR||tok==token.STRING {nid=2; raw="LIT"}
   else if tok.IsKeyword() {nid=1000+int(tok); raw=tok.String()}
   else if tok.IsOperator() {nid=3; raw=tok.String()}
   else {nid=int(tok)+500; raw=tok.String()}
   _ = lit
   toks = append(toks, struct{id int; raw string; line int}{id: nid, raw: raw, line: fset.Position(pos).Line})
  }
  filesTokens = append(filesTokens, FileTokens{path: fpath, tokens: toks})
 }
 var global []GlobalToken
 for _, ft := range filesTokens {
  for _, ti := range ft.tokens {
   global = append(global, GlobalToken{id: ti.id, raw: ti.raw, file: ft.path, line: ti.line})
  }
  global = append(global, GlobalToken{id:0})
 }
 n:=len(global)
 suffixes:=make([]int,0,n)
 for i:=0;i<n;i++{if global[i].id!=0{suffixes=append(suffixes,i)}}
 sort.Slice(suffixes, func(a,b int) bool{
  ia:=suffixes[a]; ib:=suffixes[b]
  for {
   if ia>=n||ib>=n{return ia>ib}
   if global[ia].id==0||global[ib].id==0{
    if global[ia].id==0&&global[ib].id==0{return false}
    if global[ia].id==0{return true}
    return false
   }
   if global[ia].id!=global[ib].id{return global[ia].id<global[ib].id}
   ia++; ib++
  }
 })
 lcp:=make([]int, len(suffixes))
 for i:=1;i<len(suffixes);i++{
  a:=suffixes[i-1]; b:=suffixes[i]; l:=0
  for {
   if a+l>=n||b+l>=n{break}
   if global[a+l].id==0||global[b+l].id==0{break}
   if global[a+l].id!=global[b+l].id{break}
   l++
  }
  lcp[i]=l
 }
 type Occ struct{file string; line int; pos int; endLine int; length int; raw string}
 var groups [][]Occ
 i:=1
 for i<len(suffixes){
  if lcp[i]<thresh{i++;continue}
  start:=i-1
  minLCP:=lcp[i]
  j:=i
  for j<len(suffixes)&&lcp[j]>=thresh{
   if lcp[j]<minLCP{minLCP=lcp[j]}
   j++
  }
  var occs []Occ
  for k:=start;k<j;k++{
   pos:=suffixes[k]
   file:=global[pos].file
   line:=global[pos].line
   endLine:=line
   if pos+minLCP-1<n{
    endLine=global[pos+minLCP-1].line
   }
   // check balanced braces
   openBraces:=0
   closeBraces:=0
   var rawSeq []string
   for t:=0; t<minLCP; t++{
    if pos+t>=n{break}
    r := global[pos+t].raw
    rawSeq = append(rawSeq, r)
    if r=="{"{openBraces++}
    if r=="}"{closeBraces++}
   }
   // balanced if open==close
   balanced := openBraces==closeBraces
   // for now we will keep balanced only
   if !balanced {
    // skip this occurrence? Or skip whole group? Let's skip group if any occurrence not balanced?
    // For simplicity, we will keep group only if all occs balanced
   }
   occs=append(occs, Occ{file:file, line:line, pos:pos, endLine:endLine, length:minLCP, raw: strings.Join(rawSeq, " ")})
  }
  // check balanced for all
  balancedAll := true
  for _, o := range occs {
   // we need to recompute braces for each
   // we already have raw, but we didn't store per occ raw count, we stored in raw string but not counts
   // Let's recompute quickly: we have global raw
   openBraces:=0; closeBraces:=0
   for t:=0; t<o.length; t++{
    r := global[o.pos+t].raw
    if r=="{"{openBraces++}
    if r=="}"{closeBraces++}
   }
   if openBraces!=closeBraces{
    balancedAll=false
    break
   }
  }
  if balancedAll {
   sort.Slice(occs, func(a,b int) bool{
    if occs[a].file!=occs[b].file{return occs[a].file<occs[b].file}
    return occs[a].pos<occs[b].pos
   })
   groups=append(groups, occs)
  }
  i=j
 }
 fmt.Printf("raw groups %d after balanced filter %d thresh %d\n", len(groups), len(groups), thresh)
 // overlap filter
 var filtered [][]Occ
 for _, g := range groups {
  byFile := make(map[string][]Occ)
  for _, o := range g {byFile[o.file]=append(byFile[o.file], o)}
  overlap:=false
  for _, occs := range byFile {
   sort.Slice(occs, func(a,b int) bool{return occs[a].pos < occs[b].pos})
   for i:=1;i<len(occs);i++{
    if occs[i].pos < occs[i-1].pos+occs[i-1].length {
     overlap=true
     break
    }
   }
   if overlap{break}
  }
  if !overlap{
   filtered=append(filtered,g)
  }
 }
 fmt.Printf("after overlap %d\n", len(filtered))
 // dedup by file counts
 grouped := make(map[string][]Occ)
 maxLen := make(map[string]int)
 for _, g := range filtered {
  counts := make(map[string]int)
  for _, o := range g {counts[o.file]++}
  var sb strings.Builder
  var files []string
  for f := range counts {files=append(files,f)}
  sort.Strings(files)
  for _, f := range files {sb.WriteString(fmt.Sprintf("%s:%d|", f, counts[f]))}
  key:=sb.String()
  l:=g[0].length
  if existing, ok:=maxLen[key]; !ok || l>existing {
   maxLen[key]=l
   grouped[key]=g
  }
 }
 fmt.Printf("after dedup %d\n", len(grouped))
 for k,g := range grouped {
  fmt.Printf("key %s len %d\n", k, g[0].length)
  for _, o := range g {
   fmt.Printf("  %s:%d-%d raw %s\n", o.file, o.line, o.endLine, o.raw)
  }
 }
 fmt.Println()
}

