    return false
   }
   if global[ia].id != global[ib].id {
    return global[ia].id < global[ib].id
   }
   ia++
   ib++
  }
 })

 lcp := make([]int, len(suffixes))
 for i := 1; i < len(suffixes); i++ {
  a := suffixes[i-1]
  b := suffixes[i]
  l := 0
  for {
   if a+l >= n || b+l >= n {
    break
   }
   if global[a+l].id == 0 || global[b+l].id == 0 {
    break
   }
   if global[a+l].id != global[b+l].id {
    break
   }
   l++
  }
  lcp[i] = l
 }

 if verbose {
  log.Printf("Searching for clones")
 }

 type GroupOcc struct {
  occs []Occurrence
  length int
 }

 var rawGroups []GroupOcc
 idx := 1
 for idx < len(suffixes) {
  if lcp[idx] < thresh {
   idx++
   continue
  }
  start := idx - 1
  minLCP := lcp[idx]
  j := idx
  for j < len(suffixes) && lcp[j] >= thresh {
   if lcp[j] < minLCP {
    minLCP = lcp[j]
   }
   j++
  }
  var occs []Occurrence
  for k := start; k < j; k++ {
   pos := suffixes[k]
   file := global[pos].file
   line := global[pos].line
   endLine := line
   if pos+minLCP-1 < n {
    endLine = global[pos+minLCP-1].line
   }
   occs = append(occs, Occurrence{file: file, startLine: line, endLine: endLine, startPos: pos, length: minLCP})
  }
  // balanced filter
  balancedAll := true
  for _, o := range occs {
   openB := 0
   closeB := 0
   for t := 0; t < o.length; t++ {
    if o.startPos+t >= n {
     break
    }
    r := global[o.startPos+t].raw
    if r == "{" {
     openB++
    }
    if r == "}" {
     closeB++
    }
   }
   if openB != closeB {
    balancedAll = false
    break
   }
  }
  if !balancedAll {
   idx = j
   continue
  }
  sort.Slice(occs, func(a, b int) bool {
   if occs[a].file != occs[b].file {
    return occs[a].file < occs[b].file
   }
   if occs[a].startLine != occs[b].startLine {
    return occs[a].startLine < occs[b].startLine
   }
   return occs[a].startPos < occs[b].startPos
  })
  rawGroups = append(rawGroups, GroupOcc{occs: occs, length: minLCP})
  idx = j
 }

 // overlap filter
 var afterOverlap []GroupOcc
 for _, g := range rawGroups {
  byFile := make(map[string][]Occurrence)
  for _, o := range g.occs {
   byFile[o.file] = append(byFile[o.file], o)
  }
  overlap := false
  for _, occs := range byFile {
   sort.Slice(occs, func(a, b int) bool { return occs[a].startPos < occs[b].startPos })
   for i := 1; i < len(occs); i++ {
    if occs[i].startPos < occs[i-1].startPos+occs[i-1].length {
     overlap = true
     break
    }
   }
   if overlap {
    break
   }
  }
  if !overlap {
   afterOverlap = append(afterOverlap, g)
  }
 }

 // dedup by file occurrence counts keeping max length
 grouped := make(map[string]GroupOcc)
 maxLen := make(map[string]int)
 for _, g := range afterOverlap {
  counts := make(map[string]int)
  for _, o := range g.occs {
   counts[o.file]++
  }
  var sb strings.Builder
  var files []string
  for f := range counts {
   files = append(files, f)
  }
  sort.Strings(files)
  for _, f := range files {
   sb.WriteString(fmt.Sprintf("%s:%d|", f, counts[f]))
  }
  key := sb.String()
  if ex, ok := maxLen[key]; !ok || g.length > ex {
   maxLen[key] = g.length
   grouped[key] = g
  }
 }

 var finalGroups []GroupOcc
 for _, g := range grouped {
  finalGroups = append(finalGroups, g)
 }

 sort.Slice(finalGroups, func(a, b int) bool {
  if len(finalGroups[a].occs) == 0 || len(finalGroups[b].occs) == 0 {
   return len(finalGroups[a].occs) < len(finalGroups[b].occs)
  }
  fa := finalGroups[a].occs[0]
  fb := finalGroups[b].occs[0]
  if fa.file != fb.file {
   return fa.file < fb.file
  }
  return fa.startLine < fb.startLine
 })

 if *htmlFlag {
  fmt.Printf("<!DOCTYPE html>\n")
  fmt.Printf("<meta charset=\"utf-8\"/>\n")
  fmt.Printf("<title>Duplicates</title>\n")
  fmt.Printf("<style>\n")
  fmt.Printf("\tpre {\n")
  fmt.Printf("\t\tbackground-color: #FFD;\n")
  fmt.Printf("\t\tborder: 1px solid #E2E2E2;\n")
  fmt.Printf("\t\tpadding: 1ex;\n")
  fmt.Printf("\t}\n")
  fmt.Printf("</style>\n")
  for i, g := range finalGroups {
   fmt.Printf("<h1>#%d found %d clones</h1>\n", i+1, len(g.occs))
   for _, occ := range g.occs {
    fmt.Printf("<h2>%s:%d</h2>\n", occ.file, occ.startLine)
    lines, ok := fileLines[occ.file]
    if !ok {
     data, _ := os.ReadFile(occ.file)
     lines = strings.Split(string(data), "\n")
    }
    sIdx := occ.startLine - 1
    eIdx := occ.endLine - 1
    if sIdx < 0 {
     sIdx = 0
    }
    if eIdx >= len(lines) {
     eIdx = len(lines) - 1
    }
    var frag strings.Builder
    for li := sIdx; li <= eIdx; li++ {
     frag.WriteString(lines[li])
     if li != eIdx {
      frag.WriteString("\n")
     }
    }
    esc := html.EscapeString(frag.String())
    fmt.Printf("<pre>%s</pre>\n", esc)
   }
  }
 } else if *plumbingFlag {
  for _, g := range finalGroups {
   for i, occ := range g.occs {
    nxt := g.occs[(i+1)%len(g.occs)]
    fmt.Printf("%s:%d-%d: duplicate of %s:%d-%d\n", occ.file, occ.startLine, occ.endLine, nxt.file, nxt.startLine, nxt.endLine)
   }
  }
 } else {
  for _, g := range finalGroups {
   fmt.Printf("found %d clones:\n", len(g.occs))
   for _, occ := range g.occs {
    fmt.Printf("  %s:%d,%d\n", occ.file, occ.startLine, occ.endLine)
   }
   fmt.Printf("\n")
  }
  fmt.Printf("Found total %d clone groups.\n", len(finalGroups))
 }
}

func init() {
 log.SetFlags(log.Ldate | log.Ltime)
}
